add(17, "ดาวพุธกับดาวเสาร์", "เลขของคนที่มีสติปัญญาแตกฉาน เข้าใจเรื่องต่าง ๆ ง่าย และหยั่งรู้เหตุการณ์ล่วงหน้าได้เร็ว แต่ชีวิตมักมีอุปสรรคและขึ้น ๆ ลง ๆ",
    "ฉลาด ไหวพริบดี เข้าใจเหตุการณ์ได้ไว", "มักถูกผู้ใหญ่กดหรือให้โทษ ตำแหน่งการงานอาจไม่ยั่งยืน อาจถูกแย่งตำแหน่ง ตำราว่าไม่เหมาะกับสุภาพสตรีนัก เพราะอาจผิดหวังเรื่องความรัก แต่งงานช้า หรืออยู่คนเดียว ควรทำใจให้สงบและไม่เหลิงเมื่อรุ่งเรือง")
add(18, "ดาวอาทิตย์กับดาวราหู", "เลขที่ใกล้เคียงเลข 17 ราหูข่มอาทิตย์ ชีวิตจึงรุ่งเรืองแล้วตกต่ำได้ ไม่แน่นอน ต้องย้ายที่หรือเปลี่ยนแปลงบ่อย และมักเจอเรื่องไม่คาดคิด",
    "เหมาะกับงานเดินทางหรืองานสำรวจมากกว่างานอยู่กับที่", "มักถูกกดดัน ถูกศัตรูปองร้าย ครอบครัวอาจแตกร้าว ผิดหวังหรือพลัดพรากบ่อย ตำราว่าไม่เหมาะกับสุภาพสตรีนัก ไม่ควรทำงานเสี่ยง")
add(19, "ดาวพฤหัสบดี", "เลขนำโชคที่ตำราว่าส่งเสริมความสำเร็จของชีวิต ได้รับความอุปการะจากผู้ใหญ่หรือผู้มีอำนาจอยู่เสมอ และได้เกียรติในสังคม",
    "ใฝ่เรียนรู้ ประสบความสำเร็จ มีผู้ใหญ่ช่วยเหลือ ได้รับเกียรติ", "ธาตุไฟมีลมเป่ามาก ไฟอาจหมดเชื้อ เวลาทำงานใหญ่ต้องรอบคอบ ตำราว่าไม่เหมาะกับสุภาพสตรีนัก เพราะอาจมีปัญหาเรื่องคู่ครอง")
add(20, "ดาวจันทร์กับดาวมฤตยู", "เลขของคนช่างฝัน ชอบเปลี่ยนแปลง ปฏิรูป ไม่ชอบอยู่กับที่ กล้าทดลองและกล้าเสี่ยง ทะเยอทะยานสูง",
    "กระตือรือร้น คิดการใหญ่ ชอบวิธีใหม่ ๆ", "บางครั้งความคิดเฉไฉหรือล้ำเส้นสิทธิของผู้อื่น ทำงานคนเดียวมักไม่สำเร็จ ถ้ามีผู้บังคับบัญชาที่รอบคอบจะประสบความสำเร็จยอดเยี่ยม และโครงการใหญ่ต้องมีกำลังสนับสนุน")
